public class Main {
    static double sumNumbers(java.util.List<? extends Number> xs) {
        double sum = 0;
        for (Number n : xs) sum += n.doubleValue();
        return sum;
    }
    public static void main(String[] args) {
        System.out.println(sumNumbers(java.util.List.of(1, 2)));
    }
}

